"""Assemble results/results.md from the CSVs (no numbers typed by hand except those quoted from the logs of this run)."""
import csv, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
R = lambda n: list(csv.DictReader(open(os.path.join(ROOT, "results", n), encoding="utf-8", newline="")))
man = {r["file"]: r for r in csv.DictReader(open(os.path.join(ROOT, "manifest.csv"), encoding="utf-8", newline=""))}
prov, det, wc = R("provenance.csv"), {r["file"]: r for r in R("provenance_details.csv")}, {r["source"]: r for r in R("working_copies.csv")}
lossy, trials, lossless = R("lossy.csv"), R("lossy_trials.csv"), R("lossless.csv")
versions = open(os.path.join(ROOT, "results", "versions.txt"), encoding="utf-8").read().strip().splitlines()
fmt_n = lambda n: f"{int(n):,}"
stem = lambda f: os.path.splitext(f)[0]
order = [r["file"] for r in prov]
included = [f for f in order if f != "dsoc-laser.tif"]
L = []
a = L.append
a("# Image-format check: JPEG XL, JPEG, WebP, AVIF\n")
a("> This file was written and generated by Claude Code (an AI coding agent): the tables come from the CSV files, and the text around them is Claude Code's. 'I' means Claude Code.\n")
a("An image format check on seven source images (six used) for an article. **This is not a benchmark**: no averages, rankings or "
  "\"winner\" rows are given, no encode/decode times were measured or are reported in this round (the separate decode-speed test is described in the README), and no images are embedded; images are referred to by file name. "
  "A handful of images cannot support general conclusions.\n")
a("**Excluded:** `dsoc-laser.tif` is excluded from the lossy and lossless tables because of a strong 8x8 grid signature "
  "(blockiness ratio 1.1022, vs 1.0016 to 1.0092 for the other photographs; likely prior JPEG history, **not proven**). "
  "Its row is kept in the provenance table. This was your decision after seeing the provenance table.\n")

a("## 1. Provenance\n")
a("Blockiness ratio = at the original resolution, the mean absolute luma difference between neighbouring pixels across the 8x8 block "
  "boundary phase with the highest value, divided by the mean of the other seven phases (average of horizontal and vertical). "
  "1.00 means no 8-pixel periodicity. 'clean' means **no sign of JPEG history** in this test, not proof of none; resampling or cropping after a JPEG stage can hide the grid. "
  "The verdict rule is my own heuristic (not a standard): `suspicious` if ratio >= 1.05 and it exceeds both control periods (7 and 9 px) by more than 0.02; "
  "`unknown` if there is almost no gradient signal. Per-phase values and controls are in `results/provenance_details.csv`.\n")
a("| file | camera | software / history tags | bit depth | original | downscale factor to 2000 px | original bytes | working PNG bytes | blockiness ratio | verdict |")
a("|---|---|---|---|---|---|---|---|---|---|")
for r in prov:
    ratio = r["blockiness_ratio"]
    v = r["verdict"]
    if r["file"] == "dsoc-laser.tif":
        ratio = f"**{ratio}**"; v = "**suspicious** (excluded from tests)"
    a(f"| {r['file']} | {r['camera']} | {r['software']} | {r['bit_depth']} | {r['original_dimensions']} | {r['downscale_factor_to_2000px']} | "
      f"{fmt_n(r['original_bytes'])} | {fmt_n(r['working_png_bytes'])} | {ratio} | {v} |")
a("")
a("Notes on provenance:\n")
a("- No file has a 'converted from image/jpeg' (or any JPEG) entry in its XMP history, software or derived-from tags. `summer-tanager.tif` records 'converted from image/x-canon-cr2 to image/tiff'.")
a("- Compression types: " + "; ".join(f"{f}: {det[f]['compression']}" for f in order) + ".")
a("- `coaf-logo.png` (ratio 1.4477) and `vscode-jxl-rs.png` (1.0687) have high raw ratios, but their 7- and 9-pixel controls are equally high (1.3315/1.4502 and 1.0759/1.0831): flat colours and sharp edges inflate this statistic, so these two numbers are not informative either way.")
a("- `chisinau-zoo-lake.tif` shows a period-2 alternation in its vertical profile (13.41/13.70 pairs); that is not an 8-pixel grid and I have not identified its cause.")
a("- `archives-ii.tif` and `summer-tanager.tif` carry an embedded Adobe RGB (1998) profile; the manifest does not mention this.\n")

a("## 2. Lossy at matched SSIMULACRA 2 (target 70, accepted 69 to 71)\n")
a("Cells are encoded file size in bytes at the quality setting whose decoded result scored within 70 +/- 1 against the working PNG. "
  "Achieved score and quality setting for every cell are in the detail table below. Because the accepted band is +/-1, the achieved scores differ slightly between cells, so sizes are only approximately matched. "
  "The table has no totals, averages or rankings.\n")
fm = ["JPEG", "WebP", "AVIF", "JXL"]
L2 = {(r["image"], r["format"]): r for r in lossy}
a("| image | credit | notes (from manifest.csv) | JPEG | WebP | AVIF | JXL |")
a("|---|---|---|---|---|---|---|")
def cell(r):
    if r is None: return "n/a"
    if r["status"].startswith("SKIPPED"): return "skipped (real transparency)"
    if r["status"] == "reached": return fmt_n(r["bytes"])
    return f"NOT REACHED (closest tried: q{r['quality']}, score {float(r['score']):.2f}, {fmt_n(r['bytes'])} B)"
for f in included:
    m = man[f]
    a(f"| {f} | {m['credit']}; {m['license']} | {m['notes']} | " + " | ".join(cell(L2.get((stem(f), x))) for x in fm) + " |")
a("")
a("Detail: quality setting / achieved SSIMULACRA 2 score / iterations used (max 8)\n")
a("| image | " + " | ".join(fm) + " |"); a("|---|---|---|---|---|")
for f in included:
    row = []
    for x in fm:
        r = L2.get((stem(f), x))
        if r is None or r["status"].startswith("SKIPPED"): row.append("-")
        else: row.append(f"q{r['quality']} / {float(r['score']):.2f} / {r['iterations']}" + ("" if r["status"] == "reached" else " **(not reached)**"))
    a(f"| {f} | " + " | ".join(row) + " |")
a("")
a("Every search trial (quality, score, bytes) is in `results/lossy_trials.csv`. Decoded dimensions matched the working PNG for every trial (a mismatch would have aborted the run).\n")
a("What happened on the awkward images:\n")
a("- **vscode-jxl-rs.png** (coloured text on black): JPEG and WebP **did not reach** the target. JPEG's best score was 64.89 (q99; q100 gave 64.86) and WebP's was 59.97 (q97; q99 59.75, q100 59.66): the score stopped rising, or fell, as quality approached 100. AVIF (q40) and JXL (q40) reached it. I did not test why; a plausible but **unverified** explanation is 4:2:0 chroma subsampling in the JPEG and WebP encoders (AVIF here was run 4:4:4).")
a("- **coaf-logo.png** (flat colours on real transparency): JPEG skipped (no alpha). WebP and AVIF reached the target. **JXL did not**: the score jumps between integer settings (q12: 53.33, q18: 54.27, q19: 78.96, q21: 78.64, q25: 80.17), so no integer `-q` lands within 69 to 71; the closest tried is reported. I did not try other JXL parameters (for example a continuous `-d`) because that would change the fixed setting.")
a("- Smooth gradients: the only gradient-heavy image (`dsoc-laser.tif`, night sky) is excluded, so no gradient behaviour is reported.")
a("- The remaining photographs behaved normally (the search converged within 8 iterations for all formats).\n")

a("## 3. Lossless\n")
a("'Lossless' here means pixel-identical (including alpha) to the **8-bit working PNG**, not to the original 16-bit/ICC source. Each result was decoded and compared with numpy. "
  "Baseline PNG is the working PNG re-optimized with oxipng. Cells are bytes.\n")
L3 = {}
for r in lossless: L3.setdefault((r["image"], r["format"]), []).append(r)
lf = ["PNG (oxipng)", "WebP", "AVIF", "JXL"]
a("| image | working PNG (as written) | PNG (oxipng) | WebP lossless | AVIF lossless | JXL (-d 0) |")
a("|---|---|---|---|---|---|")
def lcell(rows):
    out = []
    for r in rows:
        if r["status"] == "IDENTICAL":
            out.append(fmt_n(r["bytes"]) + ("" if r["variant"] == "default" else f" (with `{r['variant']}`)"))
        elif r["status"] == "RGB_UNDER_ALPHA0_DIFFERS":
            out.append(f"{fmt_n(r['bytes'])} (default settings: visible pixels and alpha identical, RGB under fully transparent pixels differs; **not bit-exact**)")
        else:
            out.append(f"**FAILED** ({r['note']})")
    return "; ".join(out)
for f in included:
    a(f"| {f} | {fmt_n(wc[f]['working_png_bytes'])} | " + " | ".join(lcell(L3[(stem(f), x)]) for x in lf) + " |")
a("")
a("`coaf-logo.png` WebP: with default settings cwebp changed the RGB values of fully transparent pixels (93,654 pixels; alpha and all visible pixels identical), so it is reported separately from bit-exact results; with `-exact` it is identical (5,524 bytes). No FAILED result occurred.\n")

a("## 4. Method and limits\n")
a("**Tools** (`results/versions.txt`):\n")
for l in versions: a(f"- {l}")
a("")
a("**Scorer:** SSIMULACRA 2 via `ssimulacra2.exe` from the libjxl v0.12.0 release (the JPEG XL project's reference implementation, ships with cjxl/djxl, takes PNG input). Chosen because it is the original implementation and needed no building here. It has no version flag.\n")
a("**Fixed encoder settings (same for every image):**\n")
a("- JPEG: Pillow/libjpeg-turbo, `quality=Q`, Huffman optimization, baseline, 4:2:0, no metadata (no cjpeg/ImageMagick; see deviations).")
a("- WebP: `cwebp -q Q -m 4 -mt -metadata none`; decoded with `dwebp -nodither`.")
a("- AVIF: `avifenc -q Q -s 6 -j all -y 444 -d 8`; decoded with `avifdec`.")
a("- JXL: `cjxl -q Q -e 7 --quiet`; decoded with `djxl`.")
a("- Lossless: `cwebp -lossless -z 6 -m 4 -mt -metadata none`; `avifenc --lossless -s 6 -j all`; `cjxl -d 0 -e 7`; `oxipng -o 4 --strip safe`. Variants only when needed: `cwebp -exact`.")
a("- Chroma subsampling therefore differs between formats (JPEG and WebP 4:2:0, AVIF 4:4:4, JXL none). I did not change it per format.\n")
a("**Matching rule:** per image and format, integer quality 1 to 100, binary search starting at 50, at most 8 iterations, stop at the first trial whose SSIMULACRA 2 score vs the working PNG is within 70 +/- 1. If none is within the band, the cell says NOT REACHED and shows the closest trial; nothing is adjusted. "
  "The first in-band trial is taken, not the closest to 70, so scores range from 69.02 to 70.91 across reached cells. Sizes are the encoded file sizes, including container headers.\n")
a("**Working copies:** Lanczos-3 (my own implementation with the same geometry as Pillow's resampler, because Pillow cannot resize 16-bit RGB), applied to the original-bit-depth data and rounded back to that depth; then one conversion to 8-bit sRGB. "
  "Long edge 2000 px; images at or below 2000 px keep their size (no upscaling): `coaf-logo` and `vscode-jxl-rs`. Resizing was done on encoded (gamma) values, not linear light. "
  "Working PNGs are untagged 8-bit, written with Pillow (compress level 6). SHA-256, dimensions and factors are in `results/working_copies.csv`.\n")
a("**Bit depth and colour profile:**\n")
for f in order:
    w = wc[f]
    a(f"- `{f}`: {w['source_bit_depth']}-bit; {w['icc']}; working size {w['working_dimensions']}; factor {float(w['downscale_factor']):.4f}.")
a("- The ICC conversion used lcms2 2.19.0 (via imagecodecs), relative colorimetric, to its built-in sRGB profile. For the files without a profile, sRGB is an assumption.\n")
a("**Transparency:** only `coaf-logo.png` has real alpha (opaque 34.539%, fully transparent 62.643%, partial 2.818%); alpha was kept in its working copy and passed to WebP, AVIF and JXL encoders. "
  "JPEG was skipped for it. For scoring, both the reference and each decoded result were composited onto the same fixed gray (128, 128, 128) before running SSIMULACRA 2, for every format. No source has a 100%-opaque alpha channel that needed dropping. Transparent-pixel RGB handling in lossless is described above.\n")
a("**VS Code screenshot:** `vscode-jxl-rs.png` is the author's own capture (Anna M, 15 Oct 2026) of BSD-3-Clause-licensed jxl-rs source code (c) the JPEG XL Project Authors, no endorsement implied. It is plain RGB; it contains **no transparency** (no alpha channel).\n")
a("**JPEG history:** `dsoc-laser.tif` shows a strong 8x8 grid signature aligned to the image origin in both axes (ratio 1.1070 horizontal and 1.0974 vertical; period-7/9 controls about 1.00): likely prior JPEG history, not proven, no metadata says so; excluded from tests at your request. "
  "No other image shows such a signature; that is 'no sign of JPEG history', which is not proof, particularly for the 8-bit Photoshop-saved `bush-official-portrait.tif`.\n")
a("**Limits:** six images and one run each; one speed setting per encoder; one scorer; one metric target; results depend on these settings (e.g. different speed or subsampling settings would change sizes); the lossy quality search assumes the score is roughly monotonic in quality (not always true near q100). A handful of images cannot support general conclusions.\n")

a("## 5. Failed, skipped or deviated\n")
a("**Failed / not reached:**")
a("- Lossy target not reached: `vscode-jxl-rs.png` JPEG and WebP; `coaf-logo.png` JXL (details above).")
a("- No lossless FAILED results. One non-bit-exact default: `coaf-logo.png` WebP lossless (transparent-pixel RGB), fixed with `-exact`.\n")
a("**Skipped:**")
a("- `dsoc-laser.tif`: excluded from lossy and lossless by your decision (provenance and working copy kept).")
a("- `coaf-logo.png` JPEG: skipped (real transparency).\n")
a("**Deviations from the instructions:**")
a("- JPEG encoder is Pillow's bundled libjpeg-turbo, not cjpeg or ImageMagick (the ImageMagick portable archive could not be unpacked without a BCJ2-capable extractor, and I did not use admin/choco without asking).")
a("- Tools were downloaded as official release builds into `work/tools` (libjxl, libavif, libwebp, exiftool from SourceForge because the exiftool.org link returned 404, oxipng). The libjxl zip uses deflate64, which PowerShell and tar could not extract (they left corrupt .exe files, which were deleted); I extracted it with a CRC-verified script. `pyoxipng` failed to build (no Rust), so the oxipng binary was used. No sudo/admin was used. No images or data were downloaded.")
a("- Python packages installed with pip: pillow, numpy, scipy, tifffile, imagecodecs, py7zr, zipfile-deflate64 (failed to build, unused), pyoxipng (failed to build, unused).")
a("- Bit-depth/ICC handling is my own implementation (Lanczos and conversion), described above; Pillow was not used for resizing.")
a("- `prepare.py` was run twice (the second run only fixed a duplicated 'Canon' in the camera string; outputs were bit-identical, same SHA-256). The first `lossy.py` dry-run attempt failed because of a wrong `dwebp -png` option; its partial outputs were deleted and the dry run re-run from scratch with the corrected command (`-nodither` was added in that fix).")
a("- The dry run (summer-tanager only) ran before your OK, as requested; its results are part of the tables.")
a("- Verdict thresholds and the blockiness statistic are my own heuristic.")
a("- No timings were measured in this round. Nothing needed to be skipped or reduced for speed; the quality search was not shortened.")
a("- `results/commands.log` contains every external command; the Python-library steps (resizing, ICC conversion, JPEG encode/decode with Pillow, numpy comparisons) are logged as the script invocations and, for Pillow JPEG, as `PIL.Image.save(...)` lines.")
a("- Sources were never modified (SHA-256 before and after are identical: `results/sources_sha256_before.txt`, `..._after.txt`).")
open(os.path.join(ROOT, "results", "results.md"), "w", encoding="utf-8").write("\n".join(L) + "\n")
print("written", len(L), "lines")
